import figma from "figma";

const instance = figma.selectedInstance;

const textOf = (node) =>
  node && node.type === "TEXT" ? node.textContent : undefined;

const group = textOf(instance.findText("Group"));
const finance = textOf(
  instance.findText("Label", { path: ["Finance"], traverseInstances: true }),
);
const sales = textOf(
  instance.findText("Label", { path: ["Sales"], traverseInstances: true }),
);
const marketing = textOf(
  instance.findText("Label", { path: ["Marketing"], traverseInstances: true }),
);
const supplyChain = textOf(
  instance.findText("Label", {
    path: ["Supply chain"],
    traverseInstances: true,
  }),
);
const manufacturing = textOf(
  instance.findText("Label", {
    path: ["Manufacturing"],
    traverseInstances: true,
  }),
);

export default {
  id: "Select panel",
  example: figma.code`<HvSelect open>
  <HvOptionGroup label="${group ?? ""}">
    <HvOption value="${finance ?? ""}">${finance ?? ""}</HvOption>
    <HvOption value="${sales ?? ""}">${sales ?? ""}</HvOption>
    <HvOption value="${marketing ?? ""}">${marketing ?? ""}</HvOption>
    <HvOption value="${supplyChain ?? ""}">${supplyChain ?? ""}</HvOption>
    <HvOption value="${manufacturing ?? ""}">${manufacturing ?? ""}</HvOption>
  </HvOptionGroup>
</HvSelect>`,
  imports: [
    'import { HvOption, HvOptionGroup, HvSelect } from "@pentaho/uikit-react-core";',
  ],
  metadata: { nestable: true },
};
